/**
 * A decision whose exact key is absent while another applicability of the same group is known is labelled INAPPLICABLE
 * instead of INSUFFICIENT_SUPPORT. Every decision method must give that label exactly when a scan over a snapshot of
 * the model's keys finds such a sibling, through leases, releases, observations, evictions, clear, decay and sidecar
 * round trips.
 */
class FrontierLearningModelSiblingApplicabilityTest {

	private static final FrontierCostDimension ROWS = FrontierCostDimension.OUTPUT_ROWS;
	private static final FrontierCostDimension RESULT = FrontierCostDimension.RESULT_ROWS;
	private static final FrontierCostDimension SOURCE = FrontierCostDimension.SOURCE_ROWS_SCANNED;
	private static final List<FrontierCostDimension> PHYSICAL_DIMENSIONS = List.of(RESULT, SOURCE);
	/* Every observation and decision uses the same unknown-range features, so no calibration ever refuses them. */
	private static final LearningFeatureEnvelope FEATURES = LearningFeatureEnvelope.conventionalRows(100.0d);
	private static final double PREDICTED = 100.0d;
	/* The capacity a sidecar is loaded with (FrontierLearningModel.MAX_KEYS). */
	private static final int LOADED_CAPACITY = 4096;

	private static final List<LogicalLearningKey> LOGICAL = logicalKeys("universe", 5);
	private static final List<PhysicalResidualKey> PHYSICAL = List.of(physical("a"), physical("b"), physical("c"));
	private static final List<PhysicalEventKey> EVENTS = List.of(event("event-0"), event("event-1"),
			event("event-2"));
	private static final List<LearningApplicability> APPLICABILITIES = List.of(applicability(1L), applicability(2L),
			applicability(3L), applicability(4L));

	@Test
	void logicalDecisionIsInapplicableWhenOnlyAnotherApplicabilityIsKnown() {
		FrontierLearningModel model = new FrontierLearningModel();
		model.observeLogical(LOGICAL.get(0), APPLICABILITIES.get(0), ROWS, FEATURES, 10.0d, 1L);

		assertEquals(LearningGateDecision.Outcome.INAPPLICABLE,
				model.logicalDecision(LOGICAL.get(0), APPLICABILITIES.get(1), ROWS, FEATURES, PREDICTED)
						.gate()
						.outcome());
		assertEquals(LearningGateDecision.Outcome.INSUFFICIENT_SUPPORT,
				model.logicalDecision(LOGICAL.get(1), APPLICABILITIES.get(1), ROWS, FEATURES, PREDICTED)
						.gate()
						.outcome(),
				"COVERAGE_PREREQUISITE: without a sibling applicability the same request is only unsupported");
	}

	@Test
	void logicalPopulationPhysicalDecisionIsInapplicableWhenOnlyAnotherApplicabilityIsKnown() {
		FrontierLearningModel model = new FrontierLearningModel();
		model.observePhysical(LOGICAL.get(0), PHYSICAL.get(0), APPLICABILITIES.get(0), RESULT, FEATURES, 10.0d,
				20.0d, 1L);

		assertEquals(LearningGateDecision.Outcome.INAPPLICABLE,
				model.physicalDecision(LOGICAL.get(0), PHYSICAL.get(0), APPLICABILITIES.get(1), RESULT, FEATURES,
						PREDICTED).gate().outcome());
		assertEquals(LearningGateDecision.Outcome.INSUFFICIENT_SUPPORT,
				model.physicalDecision(LOGICAL.get(0), PHYSICAL.get(1), APPLICABILITIES.get(1), RESULT, FEATURES,
						PREDICTED).gate().outcome(),
				"COVERAGE_PREREQUISITE: a sibling under another physical key is not a sibling");
	}

	@Test
	void eventPopulationPhysicalDecisionIsInapplicableWhenOnlyAnotherApplicabilityIsKnown() {
		FrontierLearningModel model = new FrontierLearningModel();
		ResolvedCells lease = model.resolvePhysical(EVENTS.get(0), PHYSICAL.get(0), APPLICABILITIES.get(0), false);
		assertNotNull(lease);

		assertEquals(LearningGateDecision.Outcome.INAPPLICABLE,
				model.physicalDecision(EVENTS.get(0), PHYSICAL.get(0), APPLICABILITIES.get(1), RESULT, FEATURES,
						PREDICTED).gate().outcome());
		assertEquals(LearningGateDecision.Outcome.INSUFFICIENT_SUPPORT,
				model.physicalDecision(EVENTS.get(1), PHYSICAL.get(0), APPLICABILITIES.get(1), RESULT, FEATURES,
						PREDICTED).gate().outcome(),
				"COVERAGE_PREREQUISITE: a sibling of another event population is not a sibling");
		model.release(lease);
	}

	@Test
	void sourceRowsDecisionsLookForSiblingsUnderTheSubstitutedPredictorKey() {
		FrontierLearningModel model = new FrontierLearningModel();
		model.observePhysical(LOGICAL.get(0), PHYSICAL.get(0), APPLICABILITIES.get(0), SOURCE, FEATURES, 10.0d,
				20.0d, 1L);

		assertEquals(LearningGateDecision.Outcome.INAPPLICABLE,
				model.physicalDecision(LOGICAL.get(0), PHYSICAL.get(0), APPLICABILITIES.get(1), SOURCE, FEATURES,
						PREDICTED).gate().outcome());
		assertEquals(LearningGateDecision.Outcome.INSUFFICIENT_SUPPORT,
				model.physicalDecision(LOGICAL.get(0), PHYSICAL.get(0), APPLICABILITIES.get(1), RESULT, FEATURES,
						PREDICTED).gate().outcome(),
				"the SOURCE observation lives under the source-rows predictor key, not under the raw key");
		assertDecisionsMatchScan(model, List.of(LOGICAL.get(0)), List.of(PHYSICAL.get(0)), List.of(),
				APPLICABILITIES, "after a SOURCE observation");
	}

	@Test
	void everyDecisionMatchesAScanOfTheKeysThroughRandomLifecycles() throws IOException {
		for (long seed = 1L; seed <= 16L; seed++) {
			new Lifecycle(seed, 2 + (int) (seed % 5L)).run(240);
		}
	}

	@Test
	void loadingMoreKeysThanTheCapacityForgetsTheEvictedGroups() throws IOException {
		int evicted = 64;
		FrontierLearningModel writer = new FrontierLearningModel(LOADED_CAPACITY + evicted);
		List<LogicalLearningKey> doomed = logicalKeys("doomed", evicted);
		List<LogicalLearningKey> kept = logicalKeys("kept", LOADED_CAPACITY);
		LearningApplicability first = APPLICABILITIES.get(0);
		LearningApplicability second = APPLICABILITIES.get(1);
		for (List<LogicalLearningKey> keys : List.of(doomed, kept)) {
			for (LogicalLearningKey key : keys) {
				writer.observeLogical(key, first, ROWS, FEATURES, Double.NaN, 1L);
				writer.observePhysical(key, PHYSICAL.get(0), first, RESULT, FEATURES, PREDICTED, Double.NaN, 1L);
			}
		}
		assertDecisionsMatchScan(writer, doomed, List.of(PHYSICAL.get(0)), List.of(), List.of(first, second),
				"writer");

		FrontierLearningModel loaded = roundTrip(writer);

		assertEquals(2 * LOADED_CAPACITY, loaded.cellKeys().size(),
				"COVERAGE_PREREQUISITE: loading evicted the eldest keys of both maps down to the capacity");
		assertEquals(LearningGateDecision.Outcome.INSUFFICIENT_SUPPORT,
				loaded.logicalDecision(doomed.get(0), second, ROWS, FEATURES, PREDICTED).gate().outcome(),
				"COVERAGE_PREREQUISITE: the evicted group no longer has a sibling");
		List<LogicalLearningKey> sample = new ArrayList<>(doomed);
		sample.addAll(kept.subList(0, evicted));
		assertDecisionsMatchScan(loaded, sample, List.of(PHYSICAL.get(0)), List.of(), List.of(first, second),
				"loaded");
	}

	/**
	 * At the measured key-map sizes (about 640 logical keys, 4,096 physical keys) every decision still matches the
	 * scan; prints how many map entries the scan visits per decision and the time per decision. Nothing here asserts on
	 * time.
	 */
	@Test
	void decisionsAtFullPhysicalCapacityMatchTheScan() {
		FrontierLearningModel model = new FrontierLearningModel();
		List<LogicalLearningKey> logical = logicalKeys("capacity", 1200);
		List<PhysicalEventKey> events = new ArrayList<>();
		for (int index = 0; index < 1200; index++) {
			events.add(event("capacity-" + index));
		}
		PhysicalResidualKey physical = PHYSICAL.get(0);
		LearningApplicability first = APPLICABILITIES.get(0);
		LearningApplicability second = APPLICABILITIES.get(1);
		LearningApplicability third = APPLICABILITIES.get(2);
		for (int index = 0; index < 320; index++) {
			model.observeLogical(logical.get(index), first, ROWS, FEATURES, Double.NaN, 1L);
			model.observeLogical(logical.get(index), second, ROWS, FEATURES, Double.NaN, 1L);
		}
		for (int index = 0; index < 1024; index++) {
			model.observePhysical(logical.get(index), physical, first, RESULT, FEATURES, PREDICTED, Double.NaN, 1L);
			model.observePhysical(logical.get(index), physical, second, RESULT, FEATURES, PREDICTED, Double.NaN, 1L);
			for (LearningApplicability applicability : List.of(first, second)) {
				ResolvedCells lease = model.resolvePhysical(events.get(index), physical, applicability, false);
				assertNotNull(lease);
				model.release(lease);
			}
		}
		List<CellKey> keys = model.cellKeys();
		List<CellKey> logicalCells = keys.stream().filter(key -> key.physicalKey() == null).toList();
		List<CellKey> physicalCells = keys.stream().filter(key -> key.physicalKey() != null).toList();
		assertEquals(640, logicalCells.size(), "COVERAGE_PREREQUISITE: logical key map at the measured size");
		assertEquals(LOADED_CAPACITY, physicalCells.size(), "COVERAGE_PREREQUISITE: physical key map at capacity");

		List<LearningApplicability> cycle = List.of(first, second, third);
		int[] logicalRequests = new int[400];
		int[] physicalRequests = new int[1200];
		for (int index = 0; index < logicalRequests.length; index++) {
			logicalRequests[index] = index;
		}
		for (int index = 0; index < physicalRequests.length; index++) {
			physicalRequests[index] = index;
		}

		long logicalEntries = 0L;
		long physicalEntries = 0L;
		long eventEntries = 0L;
		for (int index : logicalRequests) {
			LogicalLearningKey key = logical.get(index);
			LearningApplicability applicability = cycle.get(index % 3);
			Predicate<CellKey> group = cell -> key.equals(cell.logicalKey());
			logicalEntries += scanVisits(logicalCells, group, applicability);
			assertMatchesScan(logicalCells, group, applicability,
					model.logicalDecision(key, applicability, ROWS, FEATURES, PREDICTED), () -> "capacity logical");
		}
		for (int index : physicalRequests) {
			LogicalLearningKey key = logical.get(index);
			PhysicalEventKey event = events.get(index);
			LearningApplicability applicability = cycle.get(index % 3);
			Predicate<CellKey> logicalGroup = cell -> cell.eventKey() == null && key.equals(cell.logicalKey())
					&& physical.equals(cell.physicalKey());
			Predicate<CellKey> eventGroup = cell -> event.equals(cell.eventKey())
					&& physical.equals(cell.physicalKey());
			physicalEntries += scanVisits(physicalCells, logicalGroup, applicability);
			eventEntries += scanVisits(physicalCells, eventGroup, applicability);
			assertMatchesScan(physicalCells, logicalGroup, applicability,
					model.physicalDecision(key, physical, applicability, RESULT, FEATURES, PREDICTED),
					() -> "capacity physical");
			assertMatchesScan(physicalCells, eventGroup, applicability,
					model.physicalDecision(event, physical, applicability, RESULT, FEATURES, PREDICTED),
					() -> "capacity event");
		}

		long[] logicalNanos = new long[5];
		long[] physicalNanos = new long[5];
		long[] eventNanos = new long[5];
		long sink = 0L;
		for (int round = -3; round < 5; round++) {
			long start = System.nanoTime();
			for (int index : logicalRequests) {
				sink += model.logicalDecision(logical.get(index), cycle.get(index % 3), ROWS, FEATURES, PREDICTED)
						.gate()
						.outcome()
						.ordinal();
			}
			long afterLogical = System.nanoTime();
			for (int index : physicalRequests) {
				sink += model.physicalDecision(logical.get(index), physical, cycle.get(index % 3), RESULT, FEATURES,
						PREDICTED).gate().outcome().ordinal();
			}
			long afterPhysical = System.nanoTime();
			for (int index : physicalRequests) {
				sink += model.physicalDecision(events.get(index), physical, cycle.get(index % 3), RESULT, FEATURES,
						PREDICTED).gate().outcome().ordinal();
			}
			long afterEvent = System.nanoTime();
			if (round >= 0) {
				logicalNanos[round] = afterLogical - start;
				physicalNanos[round] = afterPhysical - afterLogical;
				eventNanos[round] = afterEvent - afterPhysical;
			}
		}
		report("logical", logicalCells.size(), logicalRequests.length, logicalEntries, logicalNanos);
		report("physical-logical-population", physicalCells.size(), physicalRequests.length, physicalEntries,
				physicalNanos);
		report("physical-event-population", physicalCells.size(), physicalRequests.length, eventEntries,
				eventNanos);
		System.out.println("FLM-SIBLING-APPLICABILITY sink=" + sink);
	}

	private static void report(String kind, int mapEntries, int decisions, long scanEntries, long[] nanos) {
		long[] sorted = nanos.clone();
		Arrays.sort(sorted);
		System.out.println(String.format(Locale.ROOT,
				"FLM-SIBLING-APPLICABILITY kind=%s mapEntries=%d decisions=%d scanEntriesPerDecision=%.1f"
						+ " nsPerDecision(min/median of %d rounds)=%.0f/%.0f",
				kind, mapEntries, decisions, scanEntries / (double) decisions, sorted.length,
				sorted[0] / (double) decisions, sorted[sorted.length / 2] / (double) decisions));
	}

	/** Map entries the former scan visited for one decision: up to and including its first hit, else all. */
	private static int scanVisits(List<CellKey> cells, Predicate<CellKey> group,
			LearningApplicability applicability) {
		for (int index = 0; index < cells.size(); index++) {
			CellKey cell = cells.get(index);
			if (group.test(cell) && !cell.applicability().equals(applicability)) {
				return index + 1;
			}
		}
		return cells.size();
	}

	private static final class Lifecycle {
		private final long seed;
		private final Random random;
		private final FrontierLearningModel model;
		private final List<ResolvedCells> leases = new ArrayList<>();
		private long epoch;

		Lifecycle(long seed, int maximumKeys) {
			this.seed = seed;
			this.random = new Random(seed);
			this.model = new FrontierLearningModel(maximumKeys);
		}

		void run(int steps) throws IOException {
			assertDecisionsMatchScan(model, LOGICAL, PHYSICAL, EVENTS, APPLICABILITIES, "seed " + seed + " initial");
			for (int step = 0; step < steps; step++) {
				String operation = step(model, leases);
				String context = "seed " + seed + " step " + step + " " + operation;
				assertDecisionsMatchScan(model, LOGICAL, PHYSICAL, EVENTS, APPLICABILITIES, context);
				if (random.nextInt(16) == 0) {
					FrontierLearningModel loaded = roundTrip(model);
					assertDecisionsMatchScan(loaded, LOGICAL, PHYSICAL, EVENTS, APPLICABILITIES,
							context + " then sidecar round trip");
					List<ResolvedCells> loadedLeases = new ArrayList<>();
					for (int after = 0; after < 6; after++) {
						String loadedOperation = step(loaded, loadedLeases);
						assertDecisionsMatchScan(loaded, LOGICAL, PHYSICAL, EVENTS, APPLICABILITIES,
								context + " then sidecar round trip then " + loadedOperation);
					}
				}
			}
			for (ResolvedCells lease : leases) {
				model.release(lease);
			}
		}

		private String step(FrontierLearningModel target, List<ResolvedCells> targetLeases) {
			int choice = random.nextInt(100);
			LogicalLearningKey logical = pick(LOGICAL);
			PhysicalResidualKey physical = pick(PHYSICAL);
			PhysicalEventKey event = pick(EVENTS);
			LearningApplicability applicability = pick(APPLICABILITIES);
			epoch++;
			if (choice < 22) {
				boolean resolveLogical = random.nextBoolean();
				boolean resolvePhysical = !resolveLogical || random.nextBoolean();
				boolean resolveSource = random.nextBoolean();
				keep(targetLeases, target.resolve(logical, physical, applicability, resolveLogical, resolvePhysical,
						resolveSource));
				return "resolve(" + resolveLogical + "," + resolvePhysical + "," + resolveSource + ")";
			}
			if (choice < 34) {
				keep(targetLeases, target.resolvePhysical(event, physical, applicability, random.nextBoolean()));
				return "resolvePhysical";
			}
			if (choice < 52) {
				if (!targetLeases.isEmpty()) {
					target.release(targetLeases.remove(random.nextInt(targetLeases.size())));
				}
				return "release";
			}
			if (choice < 68) {
				double actual = random.nextInt(4) == 0 ? Double.NaN : random.nextInt(1000);
				target.observeLogical(logical, applicability, ROWS, FEATURES, actual, epoch);
				return "observeLogical";
			}
			if (choice < 88) {
				double actual = random.nextInt(4) == 0 ? Double.NaN : random.nextInt(1000);
				target.observePhysical(logical, physical, applicability, pick(PHYSICAL_DIMENSIONS), FEATURES,
						PREDICTED, actual, epoch);
				return "observePhysical";
			}
			if (choice < 93) {
				target.decay(0.5d);
				return "decay(0.5)";
			}
			if (choice < 97) {
				target.clear();
				return "clear";
			}
			target.decay(0.0d);
			return "decay(0)";
		}

		private static void keep(List<ResolvedCells> targetLeases, ResolvedCells lease) {
			if (lease != null) {
				targetLeases.add(lease);
			}
		}

		private <T> T pick(List<T> values) {
			return values.get(random.nextInt(values.size()));
		}
	}

	/**
	 * Compares the INAPPLICABLE label of all three decision methods, for every combination of the given keys and
	 * applicabilities (plus absent keys and a null applicability), with a scan over a snapshot of the model's keys.
	 */
	private static void assertDecisionsMatchScan(FrontierLearningModel model, List<LogicalLearningKey> logicalKeys,
			List<PhysicalResidualKey> physicalKeys, List<PhysicalEventKey> eventKeys,
			List<LearningApplicability> applicabilities, String context) {
		List<CellKey> cells = model.cellKeys();
		List<LearningApplicability> requested = new ArrayList<>(applicabilities);
		requested.add(null);
		List<LogicalLearningKey> logicalRequests = new ArrayList<>(logicalKeys);
		logicalRequests.add(null);
		for (LogicalLearningKey logical : logicalRequests) {
			Predicate<CellKey> group = cell -> cell.physicalKey() == null && cell.logicalKey().equals(logical);
			for (LearningApplicability applicability : requested) {
				assertMatchesScan(cells, group, applicability,
						model.logicalDecision(logical, applicability, ROWS, FEATURES, PREDICTED),
						() -> context + ": logicalDecision(" + logical + ", " + applicability + ")");
			}
		}
		for (PhysicalResidualKey requestedPhysical : physicalKeys) {
			for (FrontierCostDimension dimension : PHYSICAL_DIMENSIONS) {
				PhysicalResidualKey stored = dimension == SOURCE ? requestedPhysical.sourceRowsPredictor()
						: requestedPhysical;
				for (LogicalLearningKey logical : logicalRequests) {
					Predicate<CellKey> group = cell -> cell.eventKey() == null && cell.physicalKey() != null
							&& cell.logicalKey().equals(logical) && cell.physicalKey().equals(stored);
					for (LearningApplicability applicability : requested) {
						assertMatchesScan(cells, group, applicability,
								model.physicalDecision(logical, requestedPhysical, applicability, dimension,
										FEATURES, PREDICTED),
								() -> context + ": physicalDecision(" + logical + ", " + requestedPhysical + ", "
										+ applicability + ", " + dimension + ")");
					}
				}
				for (PhysicalEventKey event : eventKeys) {
					Predicate<CellKey> group = cell -> event.equals(cell.eventKey())
							&& cell.physicalKey().equals(stored);
					for (LearningApplicability applicability : requested) {
						assertMatchesScan(cells, group, applicability,
								model.physicalDecision(event, requestedPhysical, applicability, dimension, FEATURES,
										PREDICTED),
								() -> context + ": eventDecision(" + event + ", " + requestedPhysical + ", "
										+ applicability + ", " + dimension + ")");
					}
				}
			}
		}
	}

	private static void assertMatchesScan(List<CellKey> cells, Predicate<CellKey> group,
			LearningApplicability applicability, FrontierLearningModel.DimensionDecision decision,
			Supplier<String> context) {
		boolean exact = false;
		boolean sibling = false;
		for (CellKey cell : cells) {
			if (group.test(cell)) {
				if (cell.applicability().equals(applicability)) {
					exact = true;
				} else {
					sibling = true;
				}
			}
		}
		// A null applicability is always refused; otherwise only a sibling without the exact key is.
		boolean expected = applicability == null || !exact && sibling;
		boolean actual = decision.gate().outcome() == LearningGateDecision.Outcome.INAPPLICABLE;
		if (expected != actual) {
			assertEquals(expected, actual, context.get() + " (exact key known: " + exact + ", sibling known: " + sibling
					+ ", outcome: " + decision.gate().outcome() + ")");
		}
	}

	private static FrontierLearningModel roundTrip(FrontierLearningModel model) throws IOException {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (DataOutputStream out = new DataOutputStream(bytes)) {
			model.writeTo(out, true);
		}
		try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			return FrontierLearningModel.readFrom(in, true, true);
		}
	}

	private static List<LogicalLearningKey> logicalKeys(String prefix, int count) {
		List<LogicalLearningKey> keys = new ArrayList<>(count);
		for (int index = 0; index < count; index++) {
			keys.add(LogicalLearningKey.of("join", prefix + "-expr-" + index, "children", "predicates", "v0,v1",
					"none", "bag", "store-defaults"));
		}
		return keys;
	}

	private static PhysicalResidualKey physical(String layout) {
		return PhysicalResidualKey.of("streaming", "direct", "spoc", "dependent-reopen", "none", "none", "none",
				"layout-" + layout);
	}

	private static PhysicalEventKey event(String source) {
		try (var memory = PackedCostTestSupport.providerMemory(new PackedPlannerLimits(Long.MAX_VALUE,
				Long.MAX_VALUE)); var factory = new PhysicalEventKey.Factory(source, memory)) {
			PhysicalEventKey.Origin leaf = factory.tryOrigin(PhysicalEventKey.LEAF, "leaf", null, null);
			assertNotNull(leaf);
			return new PhysicalEventKey(leaf, "frame");
		}
	}

	private static LearningApplicability applicability(long bindingShape) {
		return new LearningApplicability(bindingShape, 0L, "input:unbound", 1L, 1L, 1L);
	}
}
